from pathlib import Path
import subprocess,json
root=Path('/srv/projects/pink-iptv')
venv=root/'backend/.venv'
old=b'#!/root/pink-iptv/backend/.venv/bin/python3'
new=b'#!/srv/projects/pink-iptv/backend/.venv/bin/python3'
def run(a,t=12):
 return subprocess.run(a,capture_output=True,text=True,timeout=t)
def active(n):
 return run(['systemctl','is-active',n+'.service'],8).stdout.strip()
def bots():
 r=run(['pm2','jlist'],14)
 if r.returncode:raise RuntimeError('PM2 unavailable')
 return {x.get('name'):{'status':(x.get('pm2_env') or {}).get('status'),'pid':x.get('pid')} for x in json.loads(r.stdout) if x.get('name') in ('iptvpn_bot','telegram-robot-leads')}
names=['pink-iptv-backend','pink-vpn','lowcost-europa','fadego-staging','pm2-root','nginx','postgresql@16-main']
states={n:active(n) for n in names}
if any(v!='active' for v in states.values()):raise RuntimeError('Some systemd service not active')
b0=bots()
if any(b0.get(n,{}).get('status')!='online' for n in ('iptvpn_bot','telegram-robot-leads')):raise RuntimeError('Bot offline')
if not root.is_dir() or root.is_symlink() or not venv.is_dir():raise RuntimeError('PINK backend runtime missing')
scripts={}
for f in (venv/'bin').iterdir():
 if not f.is_file() or f.is_symlink() or f.stat().st_size>160000:continue
 with f.open('rb') as fd:head=fd.readline().rstrip(b'\r\n')
 if head==old:scripts[f]=f.read_bytes()
if len(scripts)!=17:raise RuntimeError('Expected 17 specific stale script shebangs, found '+str(len(scripts)))
config=venv/'pyvenv.cfg'
old_cfg=config.read_bytes()
if b'/root/pink-iptv/backend/.venv' not in old_cfg:raise RuntimeError('Old venv metadata absent')
git0=run(['git','-C',str(root),'status','--porcelain','--untracked-files=no'],15)
if git0.returncode:raise RuntimeError('PINK git status unavailable')
try:
 for path,blob in scripts.items():
  updated=blob.replace(old+b'\n',new+b'\n',1)
  if updated==blob or not updated.startswith(new+b'\n'):raise RuntimeError('Script patch not applied correctly: '+path.name)
  path.write_bytes(updated)
 config.write_bytes(old_cfg.replace(b'/root/pink-iptv/backend/.venv',b'/srv/projects/pink-iptv/backend/.venv'))
 for path in scripts:
  with path.open('rb') as inp:
   if inp.readline().rstrip(b'\r\n')!=new:raise RuntimeError('New shebang mismatch')
 for name in ('uvicorn','pip','pytest'):
  proc=run([str(venv/'bin'/name),'--version'],16)
  if proc.returncode:
   print('FAILED_SCRIPT='+name,'STDERR_PREFIX='+proc.stderr[:180])
   raise RuntimeError('Project tool did not execute after relocation')
 git1=run(['git','-C',str(root),'status','--porcelain','--untracked-files=no'],15)
 if git1.returncode or git1.stdout!=git0.stdout:raise RuntimeError('PINK tracked source changed')
 for name,val in states.items():
  if active(name)!=val:raise RuntimeError('Service state changed')
 if bots()!=b0:raise RuntimeError('Telegram bot state changed')
except Exception:
 for path,blob in scripts.items():path.write_bytes(blob)
 config.write_bytes(old_cfg)
 print('PINK_PYTHON_SHEBANG_ROLLBACK=APPLIED')
 raise
print('PINK_CANONICAL_PYTHON='+str(venv/'bin/python3'))
print('OLD_ABSOLUTE_SHEBANGS_FIXED='+str(len(scripts)))
print('FIXED_COMMANDS='+','.join(sorted(path.name for path in scripts)))
print('PYVENV_METADATA_CANONICAL=YES')
print('UVICORN_PIP_PYTEST_SMOKE=PASS')
print('PINK_GIT_TRACKED_STATE_PRESERVED=YES')
print('SYSTEMD_SERVICES_AND_BOTS_UNCHANGED=YES')
print('PINK_INTERPRETER_HYGIENE=PASS')
PY
